"""Write sources.bzl from Abseil's CMake/AbseilDll.cmake.

AbseilDll.cmake lists every file of the single combined library Abseil's
CMake build makes for a DLL: ABSL_INTERNAL_DLL_FILES, plus what it appends
to that list when the compiler is not MSVC. That is the whole library
without its tests, which is what BUILD compiles, so this keeps its sources.

Usage:
    sources.py SRCDIR > sources.bzl
"""

import os
import re
import sys

LIST = "ABSL_INTERNAL_DLL_FILES"


def main():
    srcdir = sys.argv[1]
    with open(os.path.join(srcdir, "CMake", "AbseilDll.cmake")) as f:
        text = f.read()

    files = []
    # The list itself, then the `list(APPEND ...)` under `if(NOT MSVC)`.
    pattern = r"(?:set|list\(APPEND)\(?\s*{}\s+(.*?)\)".format(LIST)
    blocks = re.findall(pattern, text, re.S)
    if len(blocks) != 2:
        sys.exit("expected {} to be set once and appended to once, found {}".format(LIST, len(blocks)))
    for block in blocks:
        files += re.findall(r'"([^"]+)"', block)

    sources = sorted({"absl/" + f for f in files if f.endswith(".cc")})
    for path in sources:
        if not os.path.isfile(os.path.join(srcdir, path)):
            sys.exit("{} names {}, which is not in the source tree".format(LIST, path))

    out = sys.stdout
    out.write("# SPDX-FileCopyrightText: © 2024-2026 Austin Seipp\n")
    out.write("# SPDX-License-Identifier: Apache-2.0\n\n")
    out.write("# @generated by sources.py from CMake/AbseilDll.cmake. Do not edit; see\n")
    out.write("# sources-up-to-date in BUILD.\n\n")
    out.write("SOURCES = [\n")
    for path in sources:
        out.write('    "{}",\n'.format(path))
    out.write("]\n")


if __name__ == "__main__":
    main()
